import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, BoxGeometry, OctahedronGeometry, Mesh, AmbientLight, PointLight, Vector3 } = ctx.THREE;

  // Root container
  const root = new Group();

  // Active GSAP timelines to kill on cleanup
  const activeTimelines = [];

  // --- 1. THEATRICAL BACKDROP ---
  // A gradient plane behind the element to prevent flat void and anchor the visual space.
  const backdropGeo = new BoxGeometry(8, 6, 0.1);
  const backdropMat = new MeshBasicNodeMaterial();

  // Custom TSL gradient: vertical blend between surface and ink
  const uColorSurface = vec3(0.043, 0.043, 0.063); // #0b0b10
  const uColorInk = vec3(0.086, 0.086, 0.114);    // #16161d

  backdropMat.colorNode = mix(
    uColorSurface,
    uColorInk,
    smoothstep(0.0, 1.0, uv().y)
  );

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -1.8);
  backdrop.receiveShadow = true;
  root.add(backdrop);

  // --- 2. LOCAL DRAMATIC LIGHTING ---
  // Since the parent scene provides key and ambient, we add a focused accent and rim light local to our divider.
  const rimLight = new PointLight('#ff2a38', 1.4, 6); // Accent red rim
  rimLight.position.set(2, 1, 1);
  root.add(rimLight);

  const jewelGlow = new PointLight('#ff2a38', 0.8, 3); // Centered pulsing glow
  jewelGlow.position.set(0, 0, 0.5);
  root.add(jewelGlow);

  // --- 3. THE MACHINED DIVIDER (Procedural High-Fidelity Geometry) ---
  const ornamentGroup = new Group();
  root.add(ornamentGroup);

  // Machined rule (thin metallic rod)
  const ruleGeo = new BoxGeometry(4.5, 0.02, 0.08);
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#e8ecf2', // Paper white metal
    roughness: 0.25,
    metalness: 0.9,
    transparent: true,
    opacity: 0.95
  });
  const ruleLeft = new Mesh(ruleGeo, ruleMat);
  ruleLeft.position.set(0, 0, 0);
  ornamentGroup.add(ruleLeft);

  // Little flanking brackets
  const bracketGeo = new BoxGeometry(0.12, 0.12, 0.12);
  const bracketMat = new MeshStandardNodeMaterial({
    color: '#e8ecf2',
    roughness: 0.1,
    metalness: 0.95
  });
  const bLeft = new Mesh(bracketGeo, bracketMat);
  bLeft.position.set(-1.2, 0, 0.05);
  const bRight = new Mesh(bracketGeo, bracketMat);
  bRight.position.set(1.2, 0, 0.05);
  ornamentGroup.add(bLeft, bRight);

  // Center Jewel (Machined Octahedron)
  const jewelGeo = new OctahedronGeometry(0.2, 0);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: '#ff2a38', // Signal Red Accent
    roughness: 0.05,
    metalness: 0.1,
    transmission: 0.95,
    ior: 1.6,
    thickness: 0.4,
    transparent: true,
    opacity: 0.95
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.08);
  jewel.rotation.set(Math.PI / 4, 0, Math.PI / 4);
  ornamentGroup.add(jewel);

  // Inner Core (high emission jewel seed)
  const coreGeo = new OctahedronGeometry(0.08, 0);
  const coreMat = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  const core = new Mesh(coreGeo, coreMat);
  core.position.set(0, 0, 0.08);
  ornamentGroup.add(core);

  // Ground Contact shadow
  const shadowGeo = new BoxGeometry(4.0, 0.05, 0.01);
  const shadowMat = new MeshBasicNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.6
  });
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.position.set(0, -0.4, -0.2);
  ornamentGroup.add(contactShadow);

  // --- 4. GLB LOAD AND ASSET AUGMENTATION ---
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const glbScene = gltf.scene;

      // Scale and position the GLB asset to frame nicely behind or around the center jewel
      glbScene.scale.set(0.65, 0.65, 0.65);
      glbScene.position.set(0, 0, -0.2);

      glbScene.traverse((child) => {
        if (child.isMesh) {
          child.castShadow = true;
          child.receiveShadow = true;
          // Apply machined aesthetics if not pre-textured
          if (child.material) {
            child.material.roughness = Math.max(child.material.roughness, 0.3);
            child.material.metalness = Math.min(child.material.metalness, 0.55);
          }
        }
      });

      ornamentGroup.add(glbScene);
    }).catch((err) => {
      console.warn("Failed loading GLB inside divider node, continuing with procedural mesh:", err);
    });
  }

  // --- 5. INTERACTION & ANIMATION LOGIC ---
  const hoverTl = gsap.timeline({ paused: true });
  activeTimelines.push(hoverTl);

  // Rise-in & subtle rotation swing on hover
  hoverTl.to(ornamentGroup.position, {
    y: 0.15,
    z: 0.2,
    duration: 0.5,
    ease: "power2.out"
  }, 0);

  hoverTl.to(jewel.rotation, {
    y: Math.PI / 2,
    z: Math.PI / 2,
    duration: 0.7,
    ease: "power2.out"
  }, 0);

  hoverTl.to(jewelGlow, {
    intensity: 1.8,
    duration: 0.4
  }, 0);

  // Setup Interaction Handlers
  root.userData.handlers = {
    pointerover: () => {
      hoverTl.play();
    },
    pointerout: () => {
      hoverTl.reverse();
    },
    pointerdown: () => {
      gsap.to(ornamentGroup.scale, {
        x: 0.95,
        y: 0.95,
        z: 0.95,
        duration: 0.12,
        ease: "power4.out"
      });
    },
    pointerup: () => {
      gsap.to(ornamentGroup.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.4,
        ease: "back.out(1.7)"
      });
      // Emit navigation/select action
      ctx.emit('hub-home.select', { target: 'divider' });
    }
  };

  // --- 6. CLEANUP ---
  root.userData.cleanup = () => {
    activeTimelines.forEach((tl) => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();
    bracketGeo.dispose();
    bracketMat.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();
    coreGeo.dispose();
    coreMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return root;
}
